12	void Halfedge_Mesh::interpolate_data(std::vector< VertexCRef > const &from, VertexRef to) {
13		assert(from.size() >= 1);
14	
15		std::map< uint32_t, float > weights;
16		for (VertexCRef const v : from) {
17			for (Vertex::Bone_Weight const &bw : v->bone_weights) {
18				weights.emplace(bw.bone, 0.0f).first->second += bw.weight;
19			}
20		}
21	
22		to->bone_weights.clear();
23		to->bone_weights.reserve(weights.size());
24		float div = 1.0f / float(from.size());
25		for (auto const &bw : weights) {
26			to->bone_weights.emplace_back(Vertex::Bone_Weight{ bw.first, div * bw.second });
27		}
28	}
