183	Vec3 Halfedge_Mesh::Vertex::normal() const {
184		Vec3 n = Vec3(0.0f, 0.0f, 0.0f);
185		Vec3 pi = position;
186		HalfedgeCRef h = halfedge;
187		//walk clockwise around the vertex:
188		do {
189			Vec3 pk = h->next->vertex->position;
190			h = h->twin->next;
191			Vec3 pj = h->next->vertex->position;
192			//pi,pk,pj is a ccw-oriented triangle covering the area of h->face incident on the vertex
193			if (!h->face->boundary) n += cross(pj - pi, pk - pi);
194		} while (h != halfedge);
195		return n.unit();
196	}
