208	Vec3 Halfedge_Mesh::Vertex::neighborhood_center() const {
209		Vec3 c;
210		float d = 0.0f; // degree (i.e., number of neighbors)
211	
212		// Iterate over neighbors.
213		HalfedgeCRef h = halfedge;
214		do {
215			 // Add the contribution of the neighbor,
216			 // and increment the number of neighbors.
217			 c += h->next->vertex->position;
218			 d += 1.0f;
219			 h = h->twin->next;
220		} while (h != halfedge);
221	
222		c /= d; // compute the average
223		return c;
224	}
