242	float Halfedge_Mesh::Vertex::gaussian_curvature() const {
243		float defect = angle_defect();
244		float area = 0.0f;
245	
246		auto h = halfedge;
247		do {
248			 area += h->face->area() / h->face->degree();
249			 h = h->twin->next;
250		} while (h != halfedge);
251	
252		return defect / area;
253	}
