256	float Halfedge_Mesh::Face::area() const {
257		float a = 0.0f;
258		HalfedgeCRef h = halfedge;
259		Vec3 b = h->vertex->position;
260		h = h->next;
261		do {
262			Vec3 pi = h->vertex->position - b;
263			Vec3 pj = h->next->vertex->position - b;
264			a += 0.5f * cross(pi, pj).norm();
265			h = h->next;
266		} while (h != halfedge);
267		return a;
268	}
