378	std::string Halfedge_Mesh::describe() const {
379	
380		//for checking whether a reference is held in a given list:
381		std::unordered_set< Vertex const * > in_vertices = element_addresses(vertices);
382		std::unordered_set< Edge const * > in_edges = element_addresses(edges);
383		std::unordered_set< Face const * > in_faces = element_addresses(faces);
384		std::unordered_set< Halfedge const * > in_halfedges = element_addresses(halfedges);
385		std::unordered_set< Vertex const * > in_free_vertices = element_addresses(free_vertices);
386		std::unordered_set< Edge const * > in_free_edges = element_addresses(free_edges);
387		std::unordered_set< Face const * > in_free_faces = element_addresses(free_faces);
388		std::unordered_set< Halfedge const * > in_free_halfedges = element_addresses(free_halfedges);
389	
390		//helpers for describing things:
391		auto desc_halfedge = [&,this](HalfedgeRef h) -> std::string {
392			if (in_halfedges.count(&*h)) return "h" + std::to_string(h->id);
393			else if (in_free_halfedges.count(&*h)) return "h[freed" + std::to_string(h->id & ~0x80000000u) + "]";
394			else if (h == halfedges.end()) return "hx";
395			else return "h?";
396		};
397		auto desc_vertex = [&,this](VertexRef v) -> std::string {
398			if (in_vertices.count(&*v)) return "v" + std::to_string(v->id);
399			else if (in_free_vertices.count(&*v)) return "v[freed" + std::to_string(v->id & ~0x80000000u) + "]";
400			else if (v == vertices.end()) return "vx";
401			else return "v?";
402		};
403		auto desc_edge = [&,this](EdgeRef e) -> std::string {
404			if (in_edges.count(&*e)) return "e" + std::to_string(e->id);
405			else if (in_free_edges.count(&*e)) return "e[freed" + std::to_string(e->id & ~0x80000000u) + "]";
406			else if (e == edges.end()) return "ex";
407			else return "e?";
408		};
409		auto desc_face = [&,this](FaceRef f) -> std::string {
410			if (in_faces.count(&*f)) return "f" + std::to_string(f->id);
411			else if (in_free_faces.count(&*f)) return "f[freed" + std::to_string(f->id & ~0x80000000u) + "]";
412			else if (f == faces.end()) return "fx";
413			else return "f?";
414		};
415	
416	
417		std::ostringstream oss;
418		oss << "Mesh with " << halfedges.size() << " halfedges, " << vertices.size() << " vertices, " << edges.size() << " edges, and " << faces.size() << " faces:\n";
419		for (auto const &h : halfedges) {
420			oss << "  [h" << h.id << "] t:" << desc_halfedge(h.twin)
421			    << " n:" << desc_halfedge(h.next)
422			    << " " << desc_vertex(h.vertex)
423			    << " " << desc_edge(h.edge)
424			    << " " << desc_face(h.face) << "\n";
425		}
426		for (auto const &v : vertices) {
427			oss << "  [v" << v.id << "] " << desc_halfedge(v.halfedge) << " @ " << v.position << "\n";
428		}
429		for (auto const &e : edges) {
430			oss << "  [e" << e.id << "] " << desc_halfedge(e.halfedge) << "\n";
431		}
432		for (auto const &f : faces) {
433			oss << "  [f" << f.id << "] " << desc_halfedge(f.halfedge) << "\n";
434		}
435	
436		return oss.str();
437	}
