733	Halfedge_Mesh Halfedge_Mesh::from_indexed_faces(std::vector< Vec3 > const &vertices_, 
734			std::vector< std::vector< Index > > const &faces_,
735			std::vector< std::vector< Index > > const &corner_normal_idxs,
736			std::vector< std::vector< Index > > const &corner_uv_idxs,
737			std::vector<Vec3> const &corner_normals_,
738			std::vector<Vec2> const &corner_uvs_)
739	{
740	
741		Halfedge_Mesh mesh;
742	
743		std::vector< VertexRef > vertices; //for quick lookup of vertices by index
744		vertices.reserve(vertices_.size());
745		for (auto const &v : vertices_) {
746			vertices.emplace_back(mesh.emplace_vertex());
747			vertices.back()->position = v;
748		}
749	
750	
751		std::unordered_map< std::pair< Index, Index >, HalfedgeRef > halfedges; //for quick lookup of halfedges by from/to vertex index
752	
753		uint32_t num_faces = static_cast<uint32_t>(faces_.size());
754		const bool add_corner_normals = corner_normal_idxs.size() >= num_faces;
755		const bool add_corner_uvs = corner_uv_idxs.size() >= num_faces;
756		//helper to add a face (and, later, boundary):
757		auto add_loop = [&](std::vector< Index > const &loop, bool boundary,
758						    std::vector< Index> const &n_loop = std::vector<Index>{}, 
759							std::vector< Index> const &uv_loop = std::vector<Index>{}) {
760			assert(loop.size() >= 3);
761			
762			for (uint32_t j = 0; j < loop.size(); ++j) {
763				//omit adding a face with vertices of the same index, otherwise crashes on cylinder/cone
764				if (loop[j] == loop[(j + 1) % loop.size()]) { return; }
765			}
766	
767			FaceRef face = mesh.emplace_face(boundary);
768			HalfedgeRef prev = mesh.halfedges.end(); //keep track of previous edge around face to set next pointer
769			for (uint32_t i = 0; i < loop.size(); ++i) {
770				Index a = loop[i];
771				Index b = loop[(i + 1) % loop.size()];
772				assert(a != b);
773	
774				HalfedgeRef halfedge = mesh.emplace_halfedge();
775				if (i == 0) face->halfedge = halfedge; //store first edge as face's halfedge pointer
776				halfedge->vertex = vertices[a];
777	
778				//if first to mention vertex, set vertex's halfedge pointer:
779				if (vertices[a]->halfedge == mesh.halfedges.end()) {
780					assert(!boundary); //boundary faces should never be mentioning novel vertices, since they are created second
781					vertices[a]->halfedge = halfedge;
782				}
783				halfedge->face = face;
784	
785				auto inserted = halfedges.emplace(std::make_pair(a,b), halfedge);
786				assert(inserted.second); //if edge mentioned more than once in the same direction, not an oriented, manifold mesh
787	
788				auto twin = halfedges.find(std::make_pair(b,a));
789				if (twin == halfedges.end()) {
790					assert(!boundary); //boundary faces exist only to complete edges so should *always* match
791					//not twinned yet -- create an edge just for this halfedge:
792					EdgeRef edge = mesh.emplace_edge(false);
793					halfedge->edge = edge;
794					edge->halfedge = halfedge;
795				} else {
796					//found a twin -- connect twin pointers and reference its edge:
797					assert(twin->second->twin == mesh.halfedges.end());
798					halfedge->twin = twin->second;
799					halfedge->edge = twin->second->edge;
800					twin->second->twin = halfedge;
801				}
802	
803				if (i != 0) prev->next = halfedge; //set previous halfedge's next pointer
804				prev = halfedge;
805	
806				if(add_corner_normals && i < n_loop.size()) halfedge->corner_normal = corner_normals_[n_loop[i]];
807				if(add_corner_uvs && i < uv_loop.size()) halfedge->corner_uv = corner_uvs_[uv_loop[i]];
808			}
809	
810			prev->next = face->halfedge; //set next pointer for last halfedge to first edge
811		};
812	
813		//add all faces:
814		for (uint32_t i = 0; i < num_faces; i++) {
815			if(add_corner_normals && add_corner_uvs) add_loop(faces_[i], false, corner_normal_idxs[i], corner_uv_idxs[i]);
816			else if(add_corner_normals) add_loop(faces_[i], false, corner_normal_idxs[i]);
817			else add_loop(faces_[i], false);
818		}
819	
820		// All halfedges created so far have valid next pointers, but some may be missing twins because they are at a boundary.
821		
822		std::map< Index, Index > next_on_boundary;
823	
824		//first, look for all un-twinned halfedges to figure out the shape of the boundary:
825		for (auto const &[ from_to, halfedge ] : halfedges) {
826			if (halfedge->twin == mesh.halfedges.end()) {
827				auto ret = next_on_boundary.emplace(from_to.second, from_to.first); //twin needed on the boundary
828				assert(ret.second); //every boundary vertex should have a unique successor because the boundary is "half-disc-like"
829			}
830		}
831	
832		//now pull out boundary loops until all edges are exhausted:
833		while (!next_on_boundary.empty()) {
834			std::vector< Index > loop;
835			loop.emplace_back(next_on_boundary.begin()->first);
836	
837			do {
838				//look up next hop on the boundary:
839				auto next = next_on_boundary.find(loop.back());
840				//should never be dead ends on boundary:
841				assert(next != next_on_boundary.end());
842	
843				//add next hop to loop:
844				loop.emplace_back(next->second);
845				//...and remove from nexts structure:
846				next_on_boundary.erase(next);
847			} while (loop[0] != loop.back());
848	
849			loop.pop_back(); //remove duplicated first/last element
850	
851			assert(loop.size() >= 3); //all faces must be non-degenerate
852	
853			//add boundary loop:
854			add_loop(loop, true);
855		}
856	
857		//with boundary faces created, mesh should be ready to go with all edges nicely twinned.
858	
859		//PARANOIA: this should never happen:
860		auto error = mesh.validate();
861		if (error) {
862			std::cerr << "Halfedge_Mesh from_indexed_faces failed validation: " << error->second << std::endl;
863			assert(0);
864		}
865	
866		return mesh;
867	}
868	
869	Halfedge_Mesh Halfedge_Mesh::from_indexed_mesh_with_corner_data(
870			const Indexed_Mesh& indexed_mesh, 
871			std::vector<Index> const &corner_normal_idxs_,  
872			std::vector<Index> const &corner_uv_idxs_,  
873			std::vector<Vec3> const &normals_,  
874			std::vector<Vec2> const &uvs_)
875	{ 
876	
877		//extract vertex positions and face indices from indexed_mesh:
878		std::vector< Vec3 > indexed_vertices;
879		indexed_vertices.reserve(indexed_mesh.vertices().size());
880		for (auto const &v : indexed_mesh.vertices()) {
881			indexed_vertices.emplace_back(v.pos);
882		}
883	
884		std::vector< std::vector< Index > > indexed_faces;
885		assert(indexed_mesh.indices().size() % 3 == 0);
886		indexed_faces.reserve(indexed_mesh.indices().size() / 3);
887		for (uint32_t i = 0; i < indexed_mesh.indices().size(); i += 3) {
888			indexed_faces.emplace_back(indexed_mesh.indices().begin() + i, indexed_mesh.indices().begin() + i + 3);
889		}
890	
891		std::vector< std::vector < Index > > indexed_normals;
892		assert(corner_normal_idxs_.size() % 3 == 0);
893		indexed_normals.reserve(corner_normal_idxs_.size() / 3);
894		for (uint32_t i = 0; i < corner_normal_idxs_.size(); i += 3) {
895			indexed_normals.emplace_back(corner_normal_idxs_.begin() + i, corner_normal_idxs_.begin() + i + 3);
896		}
897	
898		std::vector< std::vector < Index > > indexed_uvs;
899		assert(corner_uv_idxs_.size() % 3 == 0);
900		indexed_uvs.reserve(corner_uv_idxs_.size() / 3);
901		for (uint32_t i = 0; i < corner_uv_idxs_.size(); i += 3) {
902			indexed_uvs.emplace_back(corner_uv_idxs_.begin() + i, corner_uv_idxs_.begin() + i + 3);
903		}
904	
905		//build halfedge mesh with the extracted vertex/face data:
906		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_faces(indexed_vertices, 
907				indexed_faces, indexed_normals, indexed_uvs, normals_, uvs_);
908	
909		return mesh;
910	}
