954		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_faces(
955			std::vector< Vec3 >{
956				Vec3{-r, -r, -r}, Vec3{ r, -r, -r},
957				Vec3{-r,  r, -r}, Vec3{ r,  r, -r},
958				Vec3{-r, -r,  r}, Vec3{ r, -r,  r},
959				Vec3{-r,  r,  r}, Vec3{ r,  r,  r}
960			},
961			std::vector< std::vector< Index > >{
962				{0,2,3,1}, {4,5,7,6},
963				{0,1,5,4}, {1,3,7,5},
964				{3,2,6,7}, {2,0,4,6},
965			}
966		);
967	
968		for (auto &edge : mesh.edges) {
969			edge.sharp = true;
970		}
971		mesh.set_corner_normals(0.0f);
972		mesh.set_corner_uvs_per_face();
973	
974		return mesh;
975	}
